from __future__ import annotations

import ast
import math
import operator

MAX_LENGTH   = 256     # characters
MAX_DEPTH    = 20      # AST nesting
MAX_NODES    = 200     # total AST nodes
MAX_EXPONENT = 512     # |exponent| cap
MAX_BITS     = 100_000 # cap on integer result size (anti memory-bomb)


class ExpressionError(Exception):
    """Any user-facing expression problem. Safe to log and return."""


_ALLOWED_NODES = (
    ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant,
    ast.Load, ast.Call, ast.Name,
    ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
    ast.UAdd, ast.USub,
)

_BINOPS = {
    ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
    ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod, ast.Pow: operator.pow,
}
_UNARYOPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}

_FUNCTIONS = {
    "abs": abs, "min": min, "max": max, "round": round,
    "sqrt": math.sqrt, "log": math.log, "log10": math.log10,
    "exp": math.exp, "floor": math.floor, "ceil": math.ceil,
    "sin": math.sin, "cos": math.cos, "tan": math.tan,
}
_CONSTANTS = {"pi": math.pi, "e": math.e}


def _validate(tree: ast.AST) -> None:
    """Structural allowlist pass — runs before any evaluation."""
    count = 0
    for node in ast.walk(tree):
        count += 1
        if count > MAX_NODES:
            raise ExpressionError("expression too complex")
        if not isinstance(node, _ALLOWED_NODES):
            raise ExpressionError(f"disallowed construct: {type(node).__name__}")


def _eval(node: ast.AST, depth: int = 0):
